INSERT INTO projects (title,title_es,category,description,description_es,outcome,outcome_es,details,details_es,stack,href,repo,code,accent,media,featured,published,sort_order) SELECT 'MeasureSystem Real-Time','MeasureSystem Real-Time','Programming','A production-ready Unity utility for inspecting dimensions and measuring distances directly in the Scene view.','Una herramienta lista para producción que inspecciona dimensiones y mide distancias directamente en la vista Scene de Unity.','Published on the Unity Asset Store by Attribute Overload','Publicada en Unity Asset Store por Attribute Overload','["Designed the editor workflow around fast selection and immediate visual feedback for level and asset teams.","Implemented the C# architecture, editor UI, unit conversion, real-time measurements and automated tests.","Supported packaging and review through the complete Unity Asset Store approval process."]','["Diseñé el flujo de editor alrededor de selección rápida y retroalimentación visual inmediata para equipos de niveles y assets.","Implementé la arquitectura en C#, interfaz de editor, conversión de unidades, mediciones en tiempo real y pruebas automatizadas.","Apoyé el empaquetado y la revisión durante todo el proceso de aprobación de Unity Asset Store."]','["Unity","C#","Editor Tools","Unit Tests"]','https://assetstore.unity.com/packages/tools/utilities/measuresystem-real-time-302689','','MS—01','cyan','[]',1,1,0 WHERE NOT EXISTS (SELECT 1 FROM content_migrations WHERE name='initial-editable-content-v1');
INSERT INTO projects (title,title_es,category,description,description_es,outcome,outcome_es,details,details_es,stack,href,repo,code,accent,media,featured,published,sort_order) SELECT 'The Exit 8 — Systems Study','The Exit 8 — Estudio de sistemas','Hybrid','A technical recreation of anomaly logic, loop progression and environmental interactions in Unreal Engine 5.','Recreación técnica de lógica de anomalías, progresión en bucle e interacciones ambientales en Unreal Engine 5.','Playable environment built around reusable Blueprint systems','Entorno jugable construido con sistemas reutilizables en Blueprint','["Developed doors, cameras, teleportation, level transitions and win-state logic as reusable Blueprints.","Combined level pacing, AI behavior, lighting and environmental audio to communicate anomalies clearly."]','["Desarrollé puertas, cámaras, teletransporte, transiciones y condición de victoria como Blueprints reutilizables.","Combiné ritmo de nivel, IA, iluminación y audio ambiental para comunicar anomalías con claridad."]','["Unreal Engine 5","Blueprints","Gameplay","Level Design"]','https://github.com/Simiobanana/Replicated-The-Exit-8','https://github.com/Simiobanana/Replicated-The-Exit-8','UE—02','violet','[]',0,1,10 WHERE NOT EXISTS (SELECT 1 FROM content_migrations WHERE name='initial-editable-content-v1');
INSERT INTO projects (title,title_es,category,description,description_es,outcome,outcome_es,details,details_es,stack,href,repo,code,accent,media,featured,published,sort_order) SELECT 'BananasEngine','BananasEngine','Programming','A lightweight C++ graphics engine with OBJ loading, transforms, lighting and live scene controls through ImGui.','Motor gráfico ligero en C++ con carga OBJ, transformaciones, iluminación y controles de escena mediante ImGui.','A four-month deep dive into real-time rendering fundamentals','Cuatro meses de trabajo sobre fundamentos de render en tiempo real','["Worked directly with the rendering pipeline, mesh data, camera transforms, materials and scene state.","Built practical debugging controls that made visual iteration faster and rendering behavior easier to inspect."]','["Trabajé directamente con el pipeline de render, datos de malla, cámara, materiales y estado de escena.","Construí controles de depuración para acelerar la iteración visual e inspeccionar el comportamiento del render."]','["C++","DirectX","ImGui","Rendering"]','https://github.com/Simiobanana/BananasEngine','https://github.com/Simiobanana/BananasEngine','DX—03','amber','[]',0,1,20 WHERE NOT EXISTS (SELECT 1 FROM content_migrations WHERE name='initial-editable-content-v1');
INSERT INTO projects (title,title_es,category,description,description_es,outcome,outcome_es,details,details_es,stack,href,repo,code,accent,media,featured,published,sort_order) SELECT 'Ká Hai — Interactive 3D','Ká Hai — Web 3D interactiva','Hybrid','A responsive production website with two interactive GLB viewers, camera controls and live PBR material customization.','Sitio responsivo en producción con dos visores GLB, controles de cámara y personalización de materiales PBR.','Final client website delivered and operating online','Sitio final entregado al cliente y funcionando en línea','["Connected browser-based 3D interaction with a responsive interface and an asynchronous contact workflow.","Optimized the experience for desktop and mobile while preserving product detail and direct manipulation."]','["Integré interacción 3D en navegador con una interfaz responsiva y un flujo de contacto asíncrono.","Optimicé la experiencia para escritorio y móvil conservando detalle de producto y manipulación directa."]','["JavaScript","model-viewer","PBR","Responsive Web"]','https://jdie2026.github.io/Ha-Kai/','','WEB—04','lime','[]',0,1,30 WHERE NOT EXISTS (SELECT 1 FROM content_migrations WHERE name='initial-editable-content-v1');
INSERT INTO projects (title,title_es,category,description,description_es,outcome,outcome_es,details,details_es,stack,href,repo,code,accent,media,featured,published,sort_order) SELECT 'Automaton Hunters','Cazadores de Autómatas','Hybrid','A team VR game I led while contributing directly to gameplay, interaction and interface systems.','Juego VR en equipo que lideré mientras contribuía directamente al gameplay, interacción e interfaz.','Project leadership plus hands-on gameplay programming','Liderazgo de proyecto y programación directa de gameplay','["Programmed scoring, timer, menus, enemy–bullet collisions and enemy movement along splines.","Built the complete settings flow, assisted weapon functionality and coordinated the team toward delivery."]','["Programé puntuación, temporizador, menús, colisiones enemigo–bala y movimiento de enemigos mediante splines.","Construí el flujo completo de ajustes, apoyé la funcionalidad del arma y coordiné al equipo hasta la entrega."]','["Unity","C#","VR","UI / UX","Spline AI"]','','','VR—05','rose','[]',0,1,40 WHERE NOT EXISTS (SELECT 1 FROM content_migrations WHERE name='initial-editable-content-v1');
INSERT INTO projects (title,title_es,category,description,description_es,outcome,outcome_es,details,details_es,stack,href,repo,code,accent,media,featured,published,sort_order) SELECT 'Shields, Trails, Beams & Orbs','Escudos, estelas, rayos y orbes','Art & VFX','A focused Unreal Engine 5 collection exploring readable silhouettes, energy motion and layered gameplay feedback.','Colección en Unreal Engine 5 que explora siluetas legibles, movimiento de energía y feedback de gameplay por capas.','Four reusable Niagara studies with distinct visual languages','Cuatro estudios reutilizables de Niagara con lenguajes visuales distintos','["Built shield, trail, beam and orb effects as modular visual-feedback blocks for gameplay.","Balanced materials, timing, color and particle density so each effect remains readable during action."]','["Construí efectos de escudo, estela, rayo y orbe como bloques modulares de feedback para gameplay.","Equilibré materiales, timing, color y densidad de partículas para mantener legibilidad durante la acción."]','["UE5","Niagara","Materials","VFX"]','','','VFX—06','violet','[]',0,1,50 WHERE NOT EXISTS (SELECT 1 FROM content_migrations WHERE name='initial-editable-content-v1');
INSERT INTO projects (title,title_es,category,description,description_es,outcome,outcome_es,details,details_es,stack,href,repo,code,accent,media,featured,published,sort_order) SELECT 'Environment & Material Studies','Estudios de entornos y materiales','Art & VFX','Real-time scenes studying composition, lighting, terrain, materials and asset integration.','Escenas en tiempo real para estudiar composición, iluminación, terreno, materiales e integración de assets.','World-building practice grounded in real-time constraints','Práctica de world building basada en restricciones de tiempo real','["Explored how atmosphere, composition and material response guide attention through a playable scene.","Connected artistic decisions with performance-aware workflows in Unity and Unreal Engine."]','["Exploré cómo atmósfera, composición y respuesta de materiales guían la atención en una escena jugable.","Conecté decisiones artísticas con flujos conscientes del rendimiento en Unity y Unreal Engine."]','["Unreal Engine","Unity","Blender","Substance"]','https://github.com/Simiobanana/Enviroments','https://github.com/Simiobanana/Enviroments','ART—07','amber','[]',0,1,60 WHERE NOT EXISTS (SELECT 1 FROM content_migrations WHERE name='initial-editable-content-v1');
